data: {"id":"chatcmpl-20261017230517495843527c955d568hRD5ltmA","created":1792278318,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_48ce8b3df5c24bde948894f1","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"\\\"\\\"\\\"\\nstress_test.py -- stress-test the optimal plan of model_v2 under\\nperturbed data: capacities (RHS) and profit coefficients (objective).\\n\\nFor each scenario:\\n  - re-solve exactly (vertex enumeration, generalized to any b1,b2,cA,cB)\\n  - cross-check with a dense grid scan (independent method)\\n  - compare against analytic predictions (shadow prices / optimality ranges)\\n  - report whether the ORIGINAL plan (42,16) stays feasible / optimal\\n\\\"\\\"\\\"\\n\\nfrom itertools import combinations\\n\\nTOL = 1e-9\\nX_OLD, Z_OLD = (42.0, 16.0), 2480.0\\n\\ndef solve(b1, b2, cA, cB):\\n    cons = [((2.0, 1.0), float(b1), \\\"machine\\\"),\\n            ((1.0, 3.0), float(b2), \\\"labor\\\"),\\n            ((-1.0, 0.0), 0.0, \\\"xA>=0\\\"),\\n            ((0.0, -1.0), 0.0, \\\"xB>=0\\\")]\\n    verts = []\\n    for (a1, r1, n1), (a2, r2, n2) in combinations(cons, 2):\\n        det = a1[0]*a2[1] - a1[1]*a2[0]\\n        if abs(det) < TOL:\\n            continue\\n        x = ((r1*a2[1] - a1[1]*r2)/det, (a1[0]*r2 - r1*a2[0])/det)\\n        if (x[0] >= -TOL and x[1] >= -TOL\\n                and a1[0]*x[0] + a1[1]*x[1] <= r1 + TOL\\n                and a2[0]*x[0] + a2[1]*x[1] <= r2 + TOL):\\n            x = (max(0.0, x[0]), max(0.0, x[1]))\\n            if not any(abs(x[0]-v[0][0]) < 1e-7 and abs(x[1]-v[0][1]) < 1e-7\\n                       for v in verts):\\n                verts.append((x, n1, n2))\\n    scored = sorted((cA*x[0] + cB*x[1], x, f\\\"{n1}&{n2}\\\") for x, n1, n2 in verts)\\n    zbest = max(s[0] for s in scored)\\n    opt = [(x, act) for z, x, act in scored if abs(z - zbest) <= 1e-7*max(1.0, abs(zbest))]\\n    return zbest, opt\\n\\ndef grid_check(b1, b2, cA, cB):\\n    \\\"\\\"\\\"Independent cross-check on the 0.1 lattice over [0,60] x [0,40].\\\"\\\"\\\"\\n    best, at_best = -1.0, 0\\n    for i in range(601):\\n        xa = i * 0.1\\n        for j in range(401):\\n            xb = j * 0.1\\n            if 2*xa + xb <= b1 + TOL and xa + 3*xb <= b2 + TOL:\\n                z = cA*xa + cB*xb\\n                if z > best + TOL:\\n                    best, at_best = z, 1\\n                elif abs(z - best) <= TOL:\\n                    at_best += 1\\n    return best, at_best\\n\\ndef old_plan_status(b1, b2, cA, cB, z_new):\\n    feas = (2*X_OLD[0] + X_OLD[1] <= b1 + TOL and X_OLD[0] + 3*X_OLD[1] <= b2 + TOL)\\n    z_old_newc = cA*X_OLD[0] + cB*X_OLD[1]\\n    return feas, z_old_newc, z_new - z_old_newc\\n\\nSCENARIOS = [\\n    # name                     b1   b2   cA   cB\\n    (\\\"BASE\\\",                  100,  90,  40,  50),\\n    (\\\"machine +10%\\\",          110,  90,  40,  50),\\n    (\\\"machine -10%\\\",           90,  90,  40,  50),\\n    (\\\"labor +10%\\\",            100,  99,  40,  50),\\n    (\\\"labor -10%\\\",            100,  81,  40,  50),\\n    (\\\"both cap +10%\\\",         110,  99,  40,  50),\\n    (\\\"profit A +10%\\\",         100,  90,  44,  50),\\n    (\\\"profit A -10%\\\",         100,  90,  36,  50),\\n    (\\\"profit B +10%\\\",         100,  90,  40,  55),\\n    (\\\"profit B -10%\\\",         100,  90,  40,  45),\\n    (\\\"cA at range edge 100\\\",  100,  90, 100,  50),\\n    (\\\"cA beyond range 120\\\",   100,  90, 120,  50),\\n    (\\\"cB beyond range 125\\\",   100,  90,  40, 125),\\n    (\\\"machine -80% (20h)\\\",     20,  90,  40,  50),\\n    (\\\"cA+10% AND mach+10%\\\",   110,  90,  44,  50),\\n]\\n\\nhdr = (f\\\"{'scenario':22s} {'new optimum (xA,xB)':>20s} {'Z*':>8s} \\\"\\n       f\\\"{'grid ok':>7s} {'old plan':>24s}\\\")\\nprint(hdr)\\nprint(\\\"-\\\" * len(hdr))\\n\\nfor name, b1, b2, cA, cB in SCENARIOS:\\n    z, opt = solve(b1, b2, cA, cB)\\n    zg, nb = grid_check(b1, b2, cA, cB)\\n    ok = abs(zg - z) <= 1e-6\\n    feas, z_old_c, gap = old_plan_status(b1, b2, cA, cB, z)\\n    pts = \\\" & \\\".join(f\\\"({x[0]:g},{x[1]:g})\\\" for x, _ in opt)\\n    acts = {a for _, a in opt}\\n    tag = f\\\"{pts} [{'; '.join(sorted(acts))}]\\\"\\n    old = (f\\\"feas, Z={z_old_c:g}, -{gap:g}\\\" if feas and gap > TOL else\\n           f\\\"feas & OPTIMAL\\\" if feas else\\n           f\\\"INFEASIBLE (needs 100>{b1:g} mach)\\\" if b1 < 100 else \\\"feas, Z=?\\\")\\n    if not feas:\\n        old = \\\"INFEASIBLE -> must re-plan\\\"\\n    print(f\\\"{name:22s} {tag:>20s} {z:8g} {str(ok):>7s} {old:>24s}\\\"\\n          + (\\\"\\\" if nb == 1 or len(opt) > 1 else \\\"  !!\\\"))\\n\\nprint()\\nprint(\\\"=\\\" * 74)\\nprint(\\\"ANALYTIC CROSS-CHECKS\\\")\\nprint(\\\"=\\\" * 74)\\nprint(\\\"Shadow prices y=(14,12): for RHS in basis range, Z* = 14*b1 + 12*b2\\\")\\nfor name, b1, b2 in [(\\\"machine +10%\\\", 110, 90), (\\\"machine -10%\\\", 90, 90),\\n                     (\\\"labor +10%\\\", 100, 99), (\\\"labor -10%\\\", 100, 81),\\n                     (\\\"both cap +10%\\\", 110, 99)]:\\n    pred = 14*b1 + 12*b2\\n    z, _ = solve(b1, b2, 40, 50)\\n    print(f\\\"  {name:14s}: predicted {pred:7.1f}  actual {z:7.1f}  match={abs(pred-z)<1e-6}\\\")\\n\\nprint()\\nprint(\\\"Profit ranges keeping vertex (42,16) optimal (cone condition):\\\")\\nprint(\\\"  cA in [cB/3, 2*cB] ; cB in [cA/2, 3*cA]\\\")\\nprint(f\\\"  with cB=50: cA in [{50/3:.2f}, 100]  -> +10% (44) and -10% (36) inside: \\\"\\n      f\\\"{50/3 <= 36 and 44 <= 100}\\\")\\nprint(f\\\"  with cA=40: cB in [20, 120]  -> +10% (55) and -10% (45) inside: \\\"\\n      f\\\"{20 <= 45 and 55 <= 120}\\\")\\nprint(\\\"  profit-ratio robustness: plan optimal iff cA/cB in [1/3, 2]; base ratio 0.8\\\")\\nprint(\\\"  -> cA must FALL ~58% or RISE 150% before the plan itself changes\\\")\\n\",\"path\":\"stress_test.py\"}"}}]}}]}

